#include <cstddef>
#include <stdexcept>
#include <vector>

std::vector<int> evolve(const std::vector<int>& cells, int steps) {
    if (steps < 0) throw std::invalid_argument("InvalidSteps");
    for (int cell : cells)
        if (cell != 0 && cell != 1) throw std::invalid_argument("InvalidCell");
    auto current = cells;
    std::vector<int> next(cells.size());
    for (int tick = 0; tick < steps; ++tick) {
        for (std::size_t i = 0; i < cells.size(); ++i) {
            auto left = i == 0 ? cells.size() - 1 : i - 1;
            auto right = i + 1 == cells.size() ? 0 : i + 1;
            next[i] = (current[left] + current[right]) % 2;
        }
        current.swap(next);
    }
    return current;
}

package main

import "errors"

func evolve(cells []int, steps int) ([]int, error) {
	if steps < 0 {
		return nil, errors.New("InvalidSteps")
	}
	for _, cell := range cells {
		if cell != 0 && cell != 1 {
			return nil, errors.New("InvalidCell")
		}
	}
	current, next := make([]int, len(cells)), make([]int, len(cells))
	copy(current, cells)
	for tick := 0; tick < steps; tick++ {
		for i := range cells {
			left, right := i-1, i+1
			if left < 0 {
				left = len(cells) - 1
			}
			if right == len(cells) {
				right = 0
			}
			next[i] = (current[left] + current[right]) % 2
		}
		current, next = next, current
	}
	return current, nil
}

#include <algorithm>
#include <stdexcept>
#include <vector>

struct CachedMaximum {
    std::vector<int> values;
    bool dirty = true;
    int cached = 0;
    int rebuilds = 0;
    explicit CachedMaximum(const std::vector<int>& input) : values(input) {}
    void reset(const std::vector<int>& input) {
        values = input;
        dirty = true;
    }
    void set(int index, int value) {
        if (index < 0 || static_cast<std::size_t>(index) >= values.size())
            throw std::out_of_range("InvalidIndex");
        values[index] = value;
        dirty = true;
    }
    int get() {
        if (dirty) {
            cached = values.empty() ? 0 : *std::max_element(values.begin(), values.end());
            ++rebuilds;
            dirty = false;
        }
        return cached;
    }
};

export class CachedMaximum {
    constructor(values) {
        this.rebuilds = 0;
        this.cached = 0;
        this.reset(values);
    }
    reset(values) {
        this.values = values.slice();
        this.dirty = true;
    }
    set(index, value) {
        if (index < 0 || index >= this.values.length)
            throw new RangeError("InvalidIndex");
        this.values[index] = value;
        this.dirty = true;
    }
    get() {
        if (this.dirty) {
            this.cached = this.values.length === 0 ? 0 :
                this.values.reduce((a, b) => Math.max(a, b));
            ++this.rebuilds;
            this.dirty = false;
        }
        return this.cached;
    }
}

#include <cstdint>
#include <stdexcept>
#include <vector>

struct FrameState {
    std::int32_t ticks = 0, position = 0, velocity = 0, lag = 0;
};

std::vector<FrameState> frames(std::int32_t step, const std::vector<std::int32_t>& deltas) {
    if (step <= 0) throw std::invalid_argument("InvalidStep");
    std::int32_t total = 0;
    for (auto elapsed : deltas) {
        if (elapsed < 0) throw std::invalid_argument("InvalidElapsed");
        if (elapsed > 2147483647 - total) throw std::overflow_error("TimeOverflow");
        total += elapsed;
    }
    FrameState state;
    std::vector<FrameState> output;
    for (auto elapsed : deltas) {
        state.lag += elapsed;
        while (state.lag >= step) {
            state.velocity = (state.velocity + 1) % 7;
            state.position = (state.position + state.velocity) % 97;
            ++state.ticks;
            state.lag -= step;
        }
        output.push_back(state);
    }
    return output;
}

export function frames(step, deltas) {
    if (step <= 0) throw new RangeError("InvalidStep");
    let total = 0;
    for (const elapsed of deltas) {
        if (elapsed < 0) throw new RangeError("InvalidElapsed");
        if (elapsed > 2147483647 - total) throw new RangeError("TimeOverflow");
        total += elapsed;
    }
    const state = {ticks: 0, position: 0, velocity: 0, lag: 0};
    return deltas.map(elapsed => {
        state.lag += elapsed;
        while (state.lag >= step) {
            state.velocity = (state.velocity + 1) % 7;
            state.position = (state.position + state.velocity) % 97;
            ++state.ticks;
            state.lag -= step;
        }
        return {...state};
    });
}
